def preserve_starting_prices(apps, schema_editor):
    Lot = apps.get_model("moon_rental", "AuctionLot")
    for auction in (
        apps.get_model("moon_rental", "Auction")
        .objects.using(schema_editor.connection.alias)
        .all()
        .iterator()
    ):
        Lot.objects.using(schema_editor.connection.alias).filter(auction_id=auction.pk).update(
            starting_price=auction.minimum_bid
        )


